INSERT INTO `locales_item` (`entry`,`name_loc8`,`description_loc8`) VALUES (43721,'Медная монета Сталвана','Вы, маги, отказываетесь снабдить меня тем, что лишь приблизит неизбежный исход, ожидающий двух влюбленных, один из которых столь наивен, что ничего не понимает. Горите все в своих огненных глыбах...') ON DUPLICATE KEY UPDATE `name_loc8`=IF(`name_loc8` IS NULL OR `name_loc8`='','Медная монета Сталвана',`name_loc8`), `description_loc8`=IF(`description_loc8` IS NULL OR `description_loc8`='','Вы, маги, отказываетесь снабдить меня тем, что лишь приблизит неизбежный исход, ожидающий двух влюбленных, один из которых столь наивен, что ничего не понимает. Горите все в своих огненных глыбах...',`description_loc8`);
INSERT INTO `locales_item` (`entry`,`name_loc8`,`description_loc8`) VALUES (43722,'Медная монета Верисы','Асто\'ре да шан\'ре. Турус Фуло лл\'амаре, А\'Тала Адоре. Изера\'дуна…') ON DUPLICATE KEY UPDATE `name_loc8`=IF(`name_loc8` IS NULL OR `name_loc8`='','Медная монета Верисы',`name_loc8`), `description_loc8`=IF(`description_loc8` IS NULL OR `description_loc8`='','Асто\'ре да шан\'ре. Турус Фуло лл\'амаре, А\'Тала Адоре. Изера\'дуна…',`description_loc8`);
