INSERT INTO `locales_item` (`entry`,`name_loc8`,`description_loc8`) VALUES (92802,'Наследие клана Корун','В этом свитке задокументирована история клана Корун и описание его роли в темных экспериментах, проводимых во время существования империи могу.') ON DUPLICATE KEY UPDATE `name_loc8`=IF(`name_loc8` IS NULL OR `name_loc8`='','Наследие клана Корун',`name_loc8`), `description_loc8`=IF(`description_loc8` IS NULL OR `description_loc8`='','В этом свитке задокументирована история клана Корун и описание его роли в темных экспериментах, проводимых во время существования империи могу.',`description_loc8`);
